/*
 * A004542  Expansion of sqrt(2) in base 5.
 * https://oeis.org/A004542
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, cons
 * Formula:   a(n) = floor(sqrt(2) * 5^(n-1)) mod 5; digits generated by the
 *            digit-by-digit square-root algorithm in base 5 (exact
 *            multi-precision integers)
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   cmp, sub
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "../utils/cmp.h"
#include "../utils/sub.h"

static uint32_t *P = NULL, *R = NULL, *T = NULL, *C = NULL;
static size_t PL = 0, RL = 0, TL = 0, CL = 0, cap = 0;
static unsigned char *dig = NULL;
static idx_t ndig = 0, digcap = 0;

static void ensure_cap(size_t need) {
    if (need <= cap) return;
    size_t nc = cap ? cap : 64;
    while (nc < need) nc *= 2;
    P = (uint32_t *)realloc(P, nc * sizeof(uint32_t));
    R = (uint32_t *)realloc(R, nc * sizeof(uint32_t));
    T = (uint32_t *)realloc(T, nc * sizeof(uint32_t));
    C = (uint32_t *)realloc(C, nc * sizeof(uint32_t));
    cap = nc;
}

/* x = x*m + add */
static void mulsmall(uint32_t *x, size_t *len, uint32_t m, uint32_t add) {
    uint64_t carry = add;
    size_t i;
    for (i = 0; i < *len; i++) {
        uint64_t v = (uint64_t)x[i] * m + carry;
        x[i] = (uint32_t)v;
        carry = v >> 32;
    }
    if (carry) x[(*len)++] = (uint32_t)carry;
    while (*len > 0 && x[*len - 1] == 0) (*len)--;
}

static void next_digit(void) {
    size_t m = (PL > RL ? PL : RL) + 4;
    ensure_cap(m);
    /* bring down next base-25 "pair" of 2 = 2.000... */
    mulsmall(R, &RL, 25, ndig == 0 ? 2 : 0);
    /* T = 2*5*P */
    memcpy(T, P, PL * sizeof(uint32_t));
    TL = PL;
    mulsmall(T, &TL, 10, 0);
    unsigned d;
    for (d = 4; d >= 1; d--) {
        memcpy(C, T, TL * sizeof(uint32_t));
        CL = TL;
        mulsmall(C, &CL, 1, d);
        mulsmall(C, &CL, d, 0);
        if (cmp(C, CL, R, RL) <= 0) {
            sub(R, &RL, C, CL);
            break;
        }
    }
    mulsmall(P, &PL, 5, d);
    if (ndig >= digcap) {
        digcap = digcap ? digcap * 2 : 1024;
        dig = (unsigned char *)realloc(dig, (size_t)digcap);
    }
    dig[ndig++] = (unsigned char)d;
}

seq_t a(idx_t n) {
    if (n < 1) return 0;
    while (ndig < n) next_digit();
    return (seq_t)dig[n - 1];
}
